(function(root){'use strict';
const names=['projects','stages','services','budgets','tasks','issues','costs','quotes','materials','stock','measurements','receipts','diary','teams','documents','schedule','checklists'];
const blank=()=>({version:1,...Object.fromEntries(names.map(k=>[k,[]]))});
const id=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
function validate(s){if(!s||s.version!==1||names.some(k=>!Array.isArray(s[k])))throw Error('Backup incompatível.');let ids=new Set();for(let k of names)for(let r of s[k]){if(!r||typeof r.id!=='string'||ids.has(r.id))throw Error('Registro inválido ou ID duplicado.');ids.add(r.id);if(k!=='projects'&&!s.projects.some(p=>p.id===r.project))throw Error('Registro sem obra correspondente.');}return true}
function save(s,kind,record){if(!names.includes(kind))throw Error('Cadastro desconhecido.');let n=structuredClone(s),i=n[kind].findIndex(x=>x.id===record.id);if(i<0)n[kind].push(record);else n[kind][i]=record;validate(n);return n;}
function remove(s,kind,id){let n=structuredClone(s),deleted=new Set([id]);if(kind==='projects'){for(let k of names)if(k!=='projects')for(let r of n[k])if(r.project===id)deleted.add(r.id);}for(let k of names)n[k]=n[k].filter(r=>!deleted.has(r.id)).map(r=>{let x={...r};for(let field of ['stage','activity','material','team','parent'])if(deleted.has(x[field]))x[field]='';return x});validate(n);return n;}
function importBudget(s,project,result){if(result.errors.length)throw Error('Corrija os erros da prévia antes de importar.');if(!s.projects.some(p=>p.id===project))throw Error('Selecione uma obra.');let existing=new Set([...s.stages,...s.services].filter(r=>r.project===project).map(r=>r.code));for(let r of [...result.stages,...result.services])if(existing.has(r.code))throw Error('O código '+r.code+' já existe nesta obra. Edite ou remova o cadastro antes de importar novamente.');let n=structuredClone(s),map=new Map(result.stages.map(r=>[r.code,id()]));for(let r of result.stages)n.stages.push({id:map.get(r.code),project,name:r.name,code:r.code,parent:map.get(r.parentCode)||'',notes:'Importado da aba '+result.sheet+' · '+r.sourceRow});for(let r of result.services)n.services.push({id:id(),project,name:r.name,code:r.code,stage:map.get(r.parentCode)||'',unit:r.unit,quantity:r.quantity,executed:0,labor:r.unitCosts.labor,materialCost:r.unitCosts.material,equipment:r.unitCosts.equipment,total:r.total,notes:'Importado da aba '+result.sheet+' · '+r.sourceRow});n.budgets.push({id:id(),project,name:'Orçamento importado · '+result.sheet,date:new Date().toISOString().slice(0,10),amount:result.controls.total??result.sum,subtotal:result.controls.subtotal??result.sum,tax:result.controls.tax??null,notes:'Importação de '+result.services.length+' serviços. Os valores não substituem automaticamente o valor contratado da obra.'});validate(n);return n;}
const api={blank,id,validate,save,remove,importBudget};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.AppModel=api;
})(typeof window==='undefined'?globalThis:window);
